// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.facadeimport timber.log.Timberimport android.content.Contextimport com.roshan.persona.productivity.alarm.AlarmEngineimport com.roshan.persona.productivity.alarm.AlarmInfoimport com.roshan.persona.productivity.calendar.CalendarEngineimport com.roshan.persona.productivity.calendar.CalendarEventimport com.roshan.persona.productivity.note.NoteEngineimport com.roshan.persona.productivity.note.NoteInfoimport com.roshan.persona.productivity.note.NoteSearchResultimport com.roshan.persona.productivity.reminder.ReminderEngineimport com.roshan.persona.productivity.reminder.ReminderInfoimport com.roshan.persona.productivity.reminder.SnoozeOptions/** * NOUS — Productivity Facade (Module 14 v1.2 — Step 14.5, CRITICAL). * * Single entry point for ALL productivity operations. Brain's * [com.roshan.persona.productivity.facade.ProductivitySkills] call this * facade — they never touch [AlarmEngine] / [ReminderEngine] / [NoteEngine] * / [CalendarEngine] directly. * * ## suspend + Result<T> (per strategy v1.1 §"Fix 3") * * Every method is `suspend` (because the underlying engines do I/O — * ContentResolver for calendar, Room for notes, WorkManager for reminders). * Every method returns [ProductivityResult] — never throws. * * ## Engine Scoping (per strategy v1.1 §"Shift 2") * * The facade is a **Singleton**. It holds singleton references to: *   - [ReminderEngine] (Singleton — WorkManager-backed) *   - [NoteEngine] (Singleton — Room DB) *   - [CalendarEngine] (Singleton — ContentResolver) * * [AlarmEngine] is Activity-scoped in production (survives rotation, not * process death). For the facade, we accept it as a constructor param * so the Activity can supply its own instance. The facade itself is * Singleton — it just holds a reference to whichever AlarmEngine the * current Activity registered via [setAlarmEngine]. * * ## Real Android APIs (transitively via engines) * * | Operation | Engine | Real API | * |-----------|--------|----------| * | setAlarm | AlarmEngine | AlarmManager.setAlarmClock | * | setTimer | AlarmEngine | AlarmManager.setExactAndAllowWhileIdle + Foreground Service | * | setReminder | ReminderEngine | WorkManager.OneTimeWorkRequest | * | snoozeReminder | ReminderEngine | WorkManager.cancelAllWorkByTag + new OneTimeWorkRequest | * | cancelReminder | ReminderEngine | WorkManager.cancelAllWorkByTag | * | createNote | NoteEngine | NoteEncryptionHelper (AES-GCM) + NoteStore (Room SQLCipher in prod) | * | searchNotes | NoteEngine | Fts5Utils.escapeFts5Query + NoteStore.search (FTS4 in prod) | * | getNoteForTts | NoteEngine | NoteEncryptionHelper.decrypt + MarkdownToTextParser.stripMarkdown | * | createCalendarEvent | CalendarEngine | ContentResolver.insert(CalendarContract.Events) | * | createEventWithReminder | CalendarEngine | CalendarContract.Events + CalendarContract.Reminders (per strategy v1.2 §"Polish 4") | * | getNextEvent | CalendarEngine | ContentResolver.query(CalendarContract.Events) | * | getTodayEvents | CalendarEngine | ContentResolver.query(CalendarContract.Events) | * * @see <a href="docs/strategy/module-14-productivity-strategy-v1.2-final.md">§Fix 3 + Shift 2</a> */class ProductivityFacade(    context: Context,    private val reminderEngine: ReminderEngine = ReminderEngine(context),    private val noteEngine: NoteEngine = NoteEngine(),    private val calendarEngine: CalendarEngine = CalendarEngine(context),) {    /**     * DI-friendly constructor — accepts a pre-built [NoteEngine] so the     * [ProductivityFacadeModule] can inject a [RoomNoteStore]-backed engine.     */    constructor(        context: Context,        noteEngine: NoteEngine,    ) : this(        context = context,        reminderEngine = ReminderEngine(context),        noteEngine = noteEngine,        calendarEngine = CalendarEngine(context),    )    companion object {        private const val TAG = "ProductivityFacade"    }    /**     * Current AlarmEngine (Activity-scoped — set by the Activity on resume).     *     * Until [setAlarmEngine] is called, alarm/timer operations return     * [ProductivityResult.Failure] with a clear "alarm engine not registered"     * message. This avoids NPEs during cold start.     */    @Volatile    private var alarmEngine: AlarmEngine? = null    /**     * Register the Activity-scoped [AlarmEngine].     *     * Called by the Activity in `onResume` (and cleared in `onPause`).     * This is how the Singleton facade gets a reference to the     * Activity-scoped alarm engine without leaking the Activity.     */    fun setAlarmEngine(engine: AlarmEngine?) {        alarmEngine = engine        Timber.tag(TAG).d("AlarmEngine ${if (engine != null) "registered" else "cleared"}.")    }    // ═══════════════════════════════════════════════════════════════════════════    // Alarm + Timer (delegates to AlarmEngine — Activity-scoped)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Set an alarm at a specific time.     *     * User-facing: "7 baje alarm lagao" → setAlarm("7:00", "Alarm").     *     * @param timeStr time string ("7:00", "7:00 AM", "19:00", "7 baje").     * @param label   optional alarm label.     * @return [ProductivityResult] with the created [AlarmInfo].     */    suspend fun setAlarm(timeStr: String, label: String? = null): AlarmOpResult {        val engine = alarmEngine ?: return ProductivityResult.Failure(            error = "AlarmEngine not registered.",            spokenMessage = "I can't set alarms right now. Please try again.",        )        val triggerMs = TimeParser.parseTimeToEpochMs(timeStr) ?: return ProductivityResult.Failure(            error = "Could not parse time '$timeStr'.",            spokenMessage = "I didn't understand the time '$timeStr'. Try something like '7 AM' or '19:00'.",        )        val result = engine.setAlarm(triggerMs, label ?: "Alarm")        Timber.tag(TAG).i("setAlarm('$timeStr', '$label') → ${result::class.simpleName}.")        return result.toProductivityResult()    }    /**     * Set a timer for a duration.     *     * User-facing: "10 minute ka timer lagao" → setTimer("10 minutes", "Timer").     *     * @param durationStr duration string ("10 minutes", "1 hour", "30s").     * @param label       optional timer label.     * @return [ProductivityResult] with the created [AlarmInfo].     */    suspend fun setTimer(durationStr: String, label: String? = null): AlarmOpResult {        val engine = alarmEngine ?: return ProductivityResult.Failure(            error = "AlarmEngine not registered.",            spokenMessage = "I can't set timers right now. Please try again.",        )        val durationMs = TimeParser.parseDurationToMs(durationStr) ?: return ProductivityResult.Failure(            error = "Could not parse duration '$durationStr'.",            spokenMessage = "I didn't understand the duration '$durationStr'. Try something like '10 minutes' or '1 hour'.",        )        val result = engine.setTimer(durationMs, label ?: "Timer")        Timber.tag(TAG).i("setTimer('$durationStr', '$label') → ${result::class.simpleName}.")        return result.toProductivityResult()    }    /**     * Cancel an alarm by ID.     */    suspend fun cancelAlarm(alarmId: String): ProductivityResult<Boolean> {        val engine = alarmEngine ?: return ProductivityResult.Failure(            error = "AlarmEngine not registered.",            spokenMessage = "I can't cancel alarms right now.",        )        val ok = engine.cancelAlarm(alarmId)        return if (ok) ProductivityResult.Success(true, "Alarm cancelled.")        else ProductivityResult.Failure("Alarm not found.", "I couldn't find that alarm.")    }    /**     * Get the next alarm (user asks "Mera alarm hai kya?").     */    suspend fun getNextAlarm(): ProductivityResult<AlarmInfo?> {        val engine = alarmEngine ?: return ProductivityResult.Failure(            error = "AlarmEngine not registered.",            spokenMessage = "I can't check alarms right now.",        )        val next = engine.getNextAlarm()        return ProductivityResult.Success(            data = next,            spokenMessage = next?.let { "Your next alarm is '${it.label}' at ${it.displayTime}." }                ?: "You have no alarms set.",        )    }    // ═══════════════════════════════════════════════════════════════════════════    // Reminders (delegates to ReminderEngine — Singleton, WorkManager)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Set a reminder (text + time).     *     * User-facing: "Kal 3 baje 'medicine le' reminder set karo" →     *   setReminder("medicine le", "tomorrow 3 PM").     *     * @param text    reminder text (will be AES-GCM encrypted).     * @param timeStr time string ("tomorrow 3 PM", "in 2 hours", "15:00").     * @return [ProductivityResult] with the created [ReminderInfo].     */    suspend fun setReminder(text: String, timeStr: String): ReminderOpResult {        val triggerMs = TimeParser.parseTimeToEpochMs(timeStr) ?: return ProductivityResult.Failure(            error = "Could not parse time '$timeStr'.",            spokenMessage = "I didn't understand the time '$timeStr'. Try something like '3 PM' or 'in 2 hours'.",        )        val result = reminderEngine.scheduleReminder(            triggerAtMs = triggerMs,            label = text.take(50),  // Label is the first 50 chars of the body.            body = text,        )        Timber.tag(TAG).i("setReminder('$text', '$timeStr') → ${result::class.simpleName}.")        return result.toProductivityResult()    }    /**     * Snooze a reminder by ID.     *     * @param reminderId the reminder ID.     * @param snoozeMs   snooze duration in ms (default 5 minutes).     */    suspend fun snoozeReminder(        reminderId: String,        snoozeMs: Long = SnoozeOptions().snoozeMs,    ): ReminderOpResult {        val result = reminderEngine.snoozeReminder(reminderId, snoozeMs)        Timber.tag(TAG).i("snoozeReminder('$reminderId') → ${result::class.simpleName}.")        return result.toProductivityResult()    }    /**     * Cancel a reminder by ID.     */    suspend fun cancelReminder(reminderId: String): ProductivityResult<Boolean> {        val ok = reminderEngine.cancelReminder(reminderId)        return if (ok) ProductivityResult.Success(true, "Reminder cancelled.")        else ProductivityResult.Failure("Reminder not found.", "I couldn't find that reminder.")    }    /**     * Get the next reminder.     */    suspend fun getNextReminder(): ProductivityResult<ReminderInfo?> {        val next = reminderEngine.getNextReminder()        return ProductivityResult.Success(            data = next,            spokenMessage = next?.let { "Your next reminder is '${it.label}' at ${it.displayTime}." }                ?: "You have no reminders set.",        )    }    // ═══════════════════════════════════════════════════════════════════════════    // Notes (delegates to NoteEngine — Singleton, encrypted Room DB)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Create a new note.     *     * User-facing: "Note banao 'buy milk'" → createNote("buy milk").     *     * @param text note body (will be AES-GCM encrypted + markdown-stripped for FTS).     * @param title optional title (defaults to first 50 chars of body).     */    suspend fun createNote(text: String, title: String? = null): NoteOpResult {        val resolvedTitle = title?.takeIf { it.isNotBlank() } ?: text.take(50)        val result = noteEngine.createNote(title = resolvedTitle, body = text)        Timber.tag(TAG).i("createNote('${resolvedTitle.take(20)}...') → ${result::class.simpleName}.")        return result.toProductivityResult()    }    /**     * Get a note's body as plain text for TTS (decrypts + strips markdown).     *     * @param noteId the note ID.     */    suspend fun getNoteForTts(noteId: String): ProductivityResult<String> {        val result = noteEngine.getNoteForTts(noteId)        return result.toProductivityResult()    }    /**     * Search notes (uses Fts5Utils.escapeFts5Query for sanitization).     *     * User-facing: "meeting ke notes dhoondo" → searchNotes("meeting").     */    suspend fun searchNotes(query: String): NoteSearchOpResult {        val result = noteEngine.searchNotes(query)        Timber.tag(TAG).i("searchNotes('$query') → ${result::class.simpleName}.")        return result.toProductivityResult()    }    /**     * Delete a note by ID.     */    suspend fun deleteNote(noteId: String): ProductivityResult<Boolean> {        val ok = noteEngine.deleteNote(noteId)        return if (ok) ProductivityResult.Success(true, "Note deleted.")        else ProductivityResult.Failure("Note not found.", "I couldn't find that note.")    }    // ═══════════════════════════════════════════════════════════════════════════    // Calendar (delegates to CalendarEngine — Singleton, ContentResolver)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Create a calendar event.     *     * User-facing: "Kal 3 baje meeting set karo" →     *   createCalendarEvent("Meeting", "tomorrow 3 PM", null).     *     * @param title     event title.     * @param timeStr   start time string ("tomorrow 3 PM", "in 2 hours").     * @param location  optional location.     * @param durationStr optional duration ("1 hour" default).     */    suspend fun createCalendarEvent(        title: String,        timeStr: String,        location: String? = null,        durationStr: String = "1 hour",    ): CalendarEventResult {        val startMs = TimeParser.parseTimeToEpochMs(timeStr) ?: return ProductivityResult.Failure(            error = "Could not parse time '$timeStr'.",            spokenMessage = "I didn't understand the time '$timeStr'.",        )        val durationMs = TimeParser.parseDurationToMs(durationStr) ?: (60 * 60 * 1000L)        val endMs = startMs + durationMs        val result = calendarEngine.createEvent(            title = title,            startMs = startMs,            endMs = endMs,            location = location,        )        Timber.tag(TAG).i("createCalendarEvent('$title', '$timeStr') → ${result::class.simpleName}.")        return result.toProductivityResult()    }    /**     * Create a calendar event WITH a reminder (per strategy v1.2 §"Polish 4").     *     * @param title     event title.     * @param timeStr   start time string.     * @param location  optional location.     * @param reminderMinutesBefore reminder minutes before (default 15).     */    suspend fun createCalendarEventWithReminder(        title: String,        timeStr: String,        location: String? = null,        reminderMinutesBefore: Int = 15,    ): CalendarEventResult {        val startMs = TimeParser.parseTimeToEpochMs(timeStr) ?: return ProductivityResult.Failure(            error = "Could not parse time '$timeStr'.",            spokenMessage = "I didn't understand the time '$timeStr'.",        )        val endMs = startMs + 60 * 60 * 1000L  // Default 1-hour event.        val result = calendarEngine.createEventWithReminder(            title = title,            startMs = startMs,            endMs = endMs,            location = location,            reminderMinutesBefore = reminderMinutesBefore,        )        Timber.tag(TAG).i("createCalendarEventWithReminder('$title', '$timeStr') → ${result::class.simpleName}.")        return result.toProductivityResult()    }    /**     * Get the next upcoming calendar event.     *     * User-facing: "Mera next event kya hai?" → getNextEvent().     */    suspend fun getNextEvent(): CalendarEventResult {        val result = calendarEngine.getNextEvent()        Timber.tag(TAG).i("getNextEvent() → ${result::class.simpleName}.")        return result.toProductivityResult()    }    /**     * Get today's calendar events.     *     * User-facing: "Aaj ke events batao" → getTodayEvents().     */    suspend fun getTodayEvents(): CalendarListResult {        val result = calendarEngine.getTodayEvents()        Timber.tag(TAG).i("getTodayEvents() → ${result::class.simpleName}.")        return result.toProductivityResult()    }    /**     * Delete a calendar event by ID.     */    suspend fun deleteCalendarEvent(eventId: Long): ProductivityResult<Boolean> {        val result = calendarEngine.deleteEvent(eventId)        return result.toProductivityResult()    }}
